import { useEffect, useState, useRef, useCallback } from "react";
import { Button, Grid, MenuItem, Select, Typography } from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import TableSuccessStories from "src/views/tables/TableSuccessStories";
import DialogSuccessStories from "src/views/dialog/DialogSuccessStories";

const SuccessStoriesPage = () => {
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [successStoriesData, setSuccessStoriesData] = useState([]);
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState(" ");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [successStoriesFormDialogOpen, setSuccessStoriesFormDialogOpen] =
    useState(false);
  const [successStoriesFormDialogMode, setSuccessStoriesFormDialogMode] =
    useState("add");
  const [successStoriesToEdit, setSuccessStoriesToEdit] = useState(null);

  const toggleSuccessStoriesFormDialog = (
    e,
    mode = "add",
    successStoriesToEdit = null
  ) => {
    // setSuccessStoriesFormDialogOpen((prev) => !prev);
    setSuccessStoriesFormDialogOpen((prev) => !prev);
    setSuccessStoriesFormDialogMode(mode);
    setSuccessStoriesToEdit(successStoriesToEdit);
  };

  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [storiesToDelete, setStoriesToDelete] = useState(null);

  const toggleConfirmationDialog = (e, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setStoriesToDelete(dataToDelete);
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };
    axiosInstance
      .get(ApiEndPoints.SuccessStories.list, { params })
      .then((response) => {
        setSuccessStoriesData(response.data.data);
        console.log(response.data.data);
        setTotalCount(response.data.totalItems);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  const handleSearchChange = (e) => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      setSearch(e.target.value);
    }, 500);
  };

  //SEARCH
  useEffect(() => {
    if (!search) {
      // If search input is empty, show all data
      setSuccessStoriesData(successStoriesData);
    } else {
      // Filter the contactData based on the search value
      const filtered = successStoriesData.filter((item) =>
        item.title.toLowerCase().includes(search.toLowerCase())
      );
      setSuccessStoriesData(filtered); // Set the filtered data
    }
  }, [search, successStoriesData]);

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      axiosInstance
        .delete(ApiEndPoints.SuccessStories.delete(storiesToDelete.id))
        .then((response) => response.data)
        .then((response) => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [storiesToDelete, currentPage, pageSize]
  );
  return (
    <>
      <Grid container spacing={4} className="match-height">
        <PageHeader
          title={
            <Typography variant="h5">
              <Translations text="Success Stories" />
            </Typography>
          }
          action={
            <Button
              variant="contained"
              onClick={toggleSuccessStoriesFormDialog}
            >
              Add Stories
            </Button>
          }
        />
        <Grid item xs={12}>
          <Card>
            <Box
              sx={{
                p: 5,
                pb: 0,
                display: "flex",
                flexWrap: "wrap",
                alignItems: "center",
                justifyContent: "end",
              }}
            >
              {/* <Box></Box> */}
              <Box
                sx={{
                  display: "flex",
                  flexWrap: "wrap",
                  alignItems: "center",
                  gap: 5,
                }}
              >
                <Select
                  size="small"
                  defaultValue={" "}
                  sx={{ bgcolor: "#F7FBFF" }}
                  onChange={(e) => {
                    const selectedValue = e.target.value;
                    setStatus(selectedValue === "all" ? "" : selectedValue);
                  }}
                >
                  <MenuItem disabled value={" "}>
                    <em>Status</em>
                  </MenuItem>
                  <MenuItem value={"all"}>All</MenuItem>
                  <MenuItem value={"active"}>Active</MenuItem>
                  <MenuItem value={"inactive"}>Inactive</MenuItem>
                </Select>
                <TextField
                  type="search"
                  size="small"
                  placeholder="Search"
                  onChange={handleSearchChange}
                />
              </Box>
            </Box>
            <Box sx={{ p: 5 }}>
              <TableSuccessStories
                status={status}
                search={search}
                loading={loading}
                rows={successStoriesData}
                totalCount={totalCount}
                setCurrentPage={setCurrentPage}
                currentPage={currentPage}
                setPageSize={setPageSize}
                pageSize={pageSize}
                toggleEdit={toggleSuccessStoriesFormDialog}
                toggleDelete={toggleConfirmationDialog}
              />
            </Box>
          </Card>
        </Grid>
      </Grid>
      <DialogSuccessStories
        mode={successStoriesFormDialogMode}
        open={successStoriesFormDialogOpen}
        toggle={toggleSuccessStoriesFormDialog}
        dataToEdit={successStoriesToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title="Delete Success Story"
        subtitle="Are you sure you want to delete this Success Story?"
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default SuccessStoriesPage;
